class Solution {
    public int pathSum(TreeNode root, int targetSum) {
        if(root == null) return 0;
        return countPath(root,targetSum)+pathSum(root.left,targetSum)+pathSum(root.right,targetSum);
    }

    private int countPath(TreeNode node, long targetSum){
        if(node == null) return 0;
        int res = 0;
        if(node.val == targetSum) res++;
        res += countPath(node.left,targetSum-node.val);
        res += countPath(node.right,targetSum-node.val);
        return res;
    }
}
